1	package pipeline
2	
3	import (
4		"fmt"
5		"math/rand"
6		"time"
7	
8		"strix-halo-vulkan/safetensors"
9		"strix-halo-vulkan/vk"
10		"strix-halo-vulkan/zimage/dit"
11		"strix-halo-vulkan/zimage/qwen"
12		"strix-halo-vulkan/zimage/tokenizer"
13		"strix-halo-vulkan/zimage/vae"
14	)
15	
16	// Options configures a Pipeline. The sizes are fixed at construction because
17	// every arena in it is: the text encoder is built for a maximum prompt, the
18	// transformer for a maximum unified sequence, and the VAE decoder for one
19	// latent grid.
20	type Options struct {
21		Model     string // the checkpoint root, holding transformer/, vae/, ...
22		Width     int    // image pixels; a multiple of 16
23		Height    int
24		Steps     int
25		MaxPrompt int // the longest prompt the text encoder is built for
26		// CPUHead runs the patch embedder and the final layer on the host, which
27		// is what stage 6 did. It is the slow path kept beside the device one
28		// (PIPELINE.md's rule), and it is a flag rather than a test-only control
29		// because the measurement that justifies stage 9 is the difference
30		// between the two on the same image.
31		CPUHead bool
32		// UnfusedLayout keeps the two pure-layout dispatches stage 10 removed --
33		// `pack v` and `narrow ctx` -- as their own passes. Same reason as
34		// CPUHead: the slow path is what the fast one is measured against, and
35		// the measurement is the difference between the two on the same image.
36		UnfusedLayout bool
37	}
38	
39	// Defaults fills in what was left zero.
40	func (o Options) Defaults() Options {
41		if o.Model == "" {
42			o.Model = "models/Z-Image-Turbo"
43		}
44		if o.Width == 0 {
45			o.Width = 1024
46		}
47		if o.Height == 0 {
48			o.Height = o.Width
49		}
50		if o.Steps == 0 {
51			o.Steps = 8
52		}
53		if o.MaxPrompt == 0 {
54			o.MaxPrompt = 512
55		}
56		return o
57	}
58	
59	// vaeScale is how much larger the image is than the latent grid: the decoder
60	// upsamples 8x and the transformer's patch size is 2, so both sides must be a
61	// multiple of 16.
62	const vaeScale = 8
63	
64	// Pipeline holds every stage resident: 7.07 GB of text encoder, 12.54 GB of
65	// transformer and the VAE, plus their activation arenas. Construction is what
66	// costs -- a little over twenty seconds, nearly all of it staging weights --
67	// and a Pipeline then generates images without touching the disk again.
68	type Pipeline struct {
69		opt Options
70	
71		tok *tokenizer.Tokenizer
72		enc *qwen.GPUEncoder
73	
74		cfg   *dit.Config
75		head  *dit.Head
76		stack *dit.GPUStack
77		// gpuHead is the patch embedder and the final layer on the device (stage
78		// 9). nil is the host path of stage 6, which is what it is measured
79		// against and what runs if the shapes do not suit the kernels.
80		gpuHead *dit.GPUHead
81	
82		dec *vae.GPUDecoder
83	
84		sched *FlowMatchEuler
85		scale float64 // the VAE's scaling_factor
86		shift float64 // its shift_factor
87	
88		// The three phases' block indices, in the order the transformer runs
89		// them. StackBlocks lays the stack out this way, so they follow from the
90		// config's counts.
91		noiseRefiner, contextRefiner, layers []int
92	
93		// ctl is empty in every real use except for Options.CPUHead; see controls.
94		ctl controls
95	
96		latentH, latentW int
97		imgTokens        int // the image stream before padding
98		imgTotal         int // and after
99		maxUnified       int
100	}
101	
102	// Timings is what one image cost, by stage.
103	type Timings struct {
104		Encode   time.Duration // tokenizer and the text encoder
105		Caption  time.Duration // cap_embedder and the context refiners, once per image
106		Steps    []time.Duration
107		Decode   time.Duration // the VAE
108		Total    time.Duration
109		Tokens   int // the prompt's length
110		CapTotal int // the caption stream after padding
111		Unified  int // the sequence the layers ran over
112	}
113	
114	// controls are the deliberate breakages the negative control switches on.
115	// They live here rather than in the test because what each of them breaks is
116	// the *composition* -- the order the three stages run in, the sign the
117	// scheduler is handed, which rows of the unified sequence the caption's rotary
118	// positions belong to -- and none of that is reachable from outside
119	// GenerateFrom. Every one of them still produces an image.
120	type controls struct {
121		// noNegate leaves the transformer's output as it is instead of negating
122		// it before the Euler step. The model predicts the velocity towards the
123		// noise and the schedule runs away from it; nothing about the tensor says
124		// which way it points.
125		noNegate bool
126		// staleCaption puts the *embedded* caption behind the image instead of
127		// the one the context refiners produced, i.e. skips the phase whose whole
128		// output is 32 rows of a 4128-row sequence.
129		staleCaption bool
130		// capPosFromZero starts the caption's rotary positions at 0 rather than
131		// 1, which is the off-by-one the checkpoint invites: nothing downstream
132		// of a rotary table can tell that every caption token moved one place.
133		capPosFromZero bool
134		// cpuHead runs the patch embedder and the final layer on the host, which
135		// is what stage 6 did and what stage 9's device path is compared against.
136		// Not a breakage -- it is the slow path, kept (PIPELINE.md's rule).
137		cpuHead bool
138	}
139	
140	// Step is what a progress callback is told after each denoising step.
141	//
142	// Blocks is the time in the transformer's blocks and Head the time in the CPU
143	// head and tail; they are separated because the head is the pipeline's one
144	// unoptimised piece. Latents is the state the step left, [C, H, W] -- it is the
145	// pipeline's own buffer and the next step overwrites it, so a callback that
146	// wants to keep it (to decode a preview, say) has to copy it.
147	type Step struct {
148		Index          int
149		Blocks, Head   time.Duration
150		Latents        []float32
151		Sigma, NextSig float64
152	}
153	
154	// New builds the pipeline, staging every weight onto the device.
155	func New(dev *vk.Device, opt Options) (*Pipeline, error) {
156		opt = opt.Defaults()
157		if opt.Width%(2*vaeScale) != 0 || opt.Height%(2*vaeScale) != 0 {
158			return nil, fmt.Errorf("pipeline: %dx%d; both sides must be a multiple of %d", opt.Width, opt.Height, 2*vaeScale)
159		}
160		p := &Pipeline{
161			opt:     opt,
162			latentH: opt.Height / vaeScale,
163			latentW: opt.Width / vaeScale,
164		}
165	
166		schedCfg, err := LoadSchedulerConfig(opt.Model + "/scheduler")
167		if err != nil {
168			return nil, err
169		}
170		if p.sched, err = NewFlowMatchEuler(opt.Steps, schedCfg); err != nil {
171			return nil, err
172		}
173	
174		if p.tok, err = tokenizer.Load(opt.Model + "/tokenizer"); err != nil {
175			return nil, fmt.Errorf("pipeline: tokenizer: %w", err)
176		}
177		encCfg, err := qwen.LoadConfig(opt.Model + "/text_encoder")
178		if err != nil {
179			return nil, fmt.Errorf("pipeline: text encoder config: %w", err)
180		}
181		encSet, err := safetensors.OpenSet(opt.Model + "/text_encoder")
182		if err != nil {
183			return nil, fmt.Errorf("pipeline: text encoder: %w", err)
184		}
185		p.enc, err = qwen.NewGPUEncoder(dev, encSet, encCfg, encCfg.EncoderLayers(), opt.MaxPrompt, nil)
186		encSet.Close()
187		if err != nil {
188			p.Destroy()
189			return nil, fmt.Errorf("pipeline: text encoder: %w", err)
190		}
191	
192		if p.cfg, err = dit.LoadConfig(opt.Model + "/transformer"); err != nil {
193			p.Destroy()
194			return nil, fmt.Errorf("pipeline: transformer config: %w", err)
195		}
196		ditSet, err := safetensors.OpenSet(opt.Model + "/transformer")
197		if err != nil {
198			p.Destroy()
199			return nil, fmt.Errorf("pipeline: transformer: %w", err)
200		}
201		defer ditSet.Close()
202		if p.head, err = dit.LoadHead(ditSet, p.cfg); err != nil {
203			p.Destroy()
204			return nil, fmt.Errorf("pipeline: transformer head: %w", err)
205		}
206		if p.cfg.CapFeat != encCfg.HiddenSize {
207			p.Destroy()
208			return nil, fmt.Errorf("pipeline: the transformer wants %d caption features, the encoder produces %d",
209				p.cfg.CapFeat, encCfg.HiddenSize)
210		}
211	
212		p.imgTokens = (p.latentH / p.head.Patch) * (p.latentW / p.head.Patch)
213		p.imgTotal = dit.PadTo(p.imgTokens)
214		p.maxUnified = p.imgTotal + dit.PadTo(opt.MaxPrompt)
215		// The rotary table is replaced per run and per phase; this one only has
216		// to be the right size and inside the axes' ranges.
217		ids, err := p.head.PositionIDs(opt.MaxPrompt, p.latentH, p.latentW)
218		if err != nil {
219			p.Destroy()
220			return nil, err
221		}
222		rope, err := dit.NewRoPE(ids, p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
223		if err != nil {
224			p.Destroy()
225			return nil, err
226		}
227		if p.stack, err = dit.NewGPUStack(dev, ditSet, p.cfg, rope, p.maxUnified, nil); err != nil {
228			p.Destroy()
229			return nil, fmt.Errorf("pipeline: transformer: %w", err)
230		}
231		// The head on the device. It is a small object beside the stack -- 5 MB
232		// of weights and four pipelines -- and it needs the stack to exist first,
233		// because the residual stream it writes and reads is the stack's arena.
234		p.ctl.cpuHead = opt.CPUHead
235		p.stack.FuseLayout = !opt.UnfusedLayout
236		if p.gpuHead, err = dit.NewGPUHead(p.stack, p.head); err != nil {
237			p.Destroy()
238			return nil, fmt.Errorf("pipeline: transformer head: %w", err)
239		}
240		nr := p.cfg.NRefiner
241		p.noiseRefiner = seq(0, nr)
242		p.contextRefiner = seq(nr, 2*nr)
243		p.layers = seq(2*nr, 2*nr+p.cfg.NLayers)
244	
245		vaeCfg := vae.FluxConfig()
246		p.scale, p.shift = vaeCfg.ScalingFactor, vaeCfg.ShiftFactor
247		cpu, err := vae.LoadDecoder(opt.Model+"/vae", vaeCfg)
248		if err != nil {
249			p.Destroy()
250			return nil, fmt.Errorf("pipeline: vae: %w", err)
251		}
252		if p.dec, err = vae.NewGPUDecoder(dev, cpu, p.latentH, p.latentW); err != nil {
253			p.Destroy()
254			return nil, fmt.Errorf("pipeline: vae: %w", err)
255		}
256		return p, nil
257	}
258	
259	// Destroy releases every device resource.
260	func (p *Pipeline) Destroy() {
261		if p.dec != nil {
262			p.dec.Destroy()
263		}
264		// Before the stack: the head's pipelines are bound to the stack's arenas.
265		if p.gpuHead != nil {
266			p.gpuHead.Destroy()
267		}
268		if p.stack != nil {
269			p.stack.Destroy()
270		}
271		if p.enc != nil {
272			p.enc.Destroy()
273		}
274		p.dec, p.stack, p.enc, p.gpuHead = nil, nil, nil, nil
275	}
276	
277	// Scheduler is the noise schedule the pipeline walks.
278	func (p *Pipeline) Scheduler() *FlowMatchEuler { return p.sched }
279	
280	// Latent is the grid the transformer denoises: 16 channels at an eighth of
281	// the image's size.
282	func (p *Pipeline) Latent() (channels, height, width int) {
283		return p.cfg.InChan, p.latentH, p.latentW
284	}
285	
286	// Noise draws an initial latent from a seeded Gaussian.
287	func (p *Pipeline) Noise(seed int64) []float32 {
288		rng := rand.New(rand.NewSource(seed))
289		out := make([]float32, p.cfg.InChan*p.latentH*p.latentW)
290		for i := range out {
291			out[i] = float32(rng.NormFloat64())
292		}
293		return out
294	}
295	
296	// Encode runs the tokenizer and the text encoder, and returns the caption
297	// stream the transformer's context refiners take: the hidden state embedded
298	// by cap_embedder, padded with the learned token.
299	func (p *Pipeline) Encode(prompt string) (*dit.Mat, int, error) {
300		ids, err := p.tok.EncodePrompt(prompt)
301		if err != nil {
302			return nil, 0, fmt.Errorf("pipeline: tokenizing: %w", err)
303		}
304		if len(ids) > p.opt.MaxPrompt {
305			return nil, 0, fmt.Errorf("pipeline: the prompt is %d tokens, the encoder was built for %d",
306				len(ids), p.opt.MaxPrompt)
307		}
308		hidden, err := p.enc.Forward(ids)
309		if err != nil {
310			return nil, 0, fmt.Errorf("pipeline: text encoder: %w", err)
311		}
312		cap, err := p.head.EmbedCaption(&dit.Mat{Rows: hidden.Rows, Cols: hidden.Cols, Data: hidden.Data})
313		if err != nil {
314			return nil, 0, err
315		}
316		return cap, len(ids), nil
317	}
318	
319	// Generate runs the whole pipeline: prompt in, decoded image out. The image
320	// is [3, H, W] in [-1, 1], which is what the VAE produces and what a PNG
321	// writer has to map.
322	func (p *Pipeline) Generate(prompt string, seed int64, progress func(Step)) (*vae.Tensor, *Timings, error) {
323		latents := p.Noise(seed)
324		return p.GenerateFrom(prompt, latents, progress)
325	}
326	
327	// GenerateFrom is Generate over an initial latent that is given rather than
328	// drawn, which is what makes an end-to-end comparison against diffusers
329	// possible: the two RNGs do not agree and nothing else in the pipeline is
330	// random.
331	func (p *Pipeline) GenerateFrom(prompt string, latents []float32, progress func(Step)) (*vae.Tensor, *Timings, error) {
332		if want := p.cfg.InChan * p.latentH * p.latentW; len(latents) != want {
333			return nil, nil, fmt.Errorf("pipeline: %d latents, want C*H*W = %d", len(latents), want)
334		}
335		tm := &Timings{}
336		whole := time.Now()
337	
338		// --- the caption, once per image ---------------------------------
339		t0 := time.Now()
340		cap, tokens, err := p.Encode(prompt)
341		if err != nil {
342			return nil, nil, err
343		}
344		tm.Encode = time.Since(t0)
345		tm.Tokens, tm.CapTotal = tokens, cap.Rows
346		unified := p.imgTotal + cap.Rows
347		tm.Unified = unified
348	
349		ids, err := p.head.PositionIDs(tokens, p.latentH, p.latentW)
350		if err != nil {
351			return nil, nil, err
352		}
353		if p.ctl.capPosFromZero {
354			for i := p.imgTotal; i < len(ids); i++ {
355				ids[i][0]--
356			}
357		}
358		ropeUnified, err := dit.NewRoPE(ids, p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
359		if err != nil {
360			return nil, nil, err
361		}
362		ropeCap, err := dit.NewRoPE(ids[p.imgTotal:], p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
363		if err != nil {
364			return nil, nil, err
365		}
366	
367		// The context refiners are the transformer's one phase that depends on
368		// neither the timestep nor the latents -- diffusers builds them with
369		// modulation=False -- so they run once per image and not once per step.
370		t0 = time.Now()
371		if err := p.stack.SetRoPE(ropeCap); err != nil {
372			return nil, nil, err
373		}
374		if err := p.stack.Upload(cap, 0, cap.Rows); err != nil {
375			return nil, nil, err
376		}
377		if err := p.stack.Run(p.contextRefiner); err != nil {
378			return nil, nil, fmt.Errorf("pipeline: context refiners: %w", err)
379		}
380		refined := p.stack.Read(p.stack.TensorX(), p.cfg.Dim)
381		tm.Caption = time.Since(t0)
382	
383		if err := p.stack.SetRoPE(ropeUnified); err != nil {
384			return nil, nil, err
385		}
386	
387		// --- the denoising loop -------------------------------------------
388		for step := 0; step < p.sched.Steps(); step++ {
389			t0 = time.Now()
390			d := Step{Index: step, Latents: latents,
391				Sigma: p.sched.Sigmas[step], NextSig: p.sched.Sigmas[step+1]}
392	
393			adaln, err := p.head.Timestep(p.sched.ModelT(step))
394			if err != nil {
395				return nil, nil, err
396			}
397			patches, err := p.head.Patchify(latents, p.latentH, p.latentW)
398			if err != nil {
399				return nil, nil, err
400			}
401			var x *dit.Mat
402			if p.gpuHead == nil || p.ctl.cpuHead {
403				if x, err = p.head.EmbedImage(patches); err != nil {
404					return nil, nil, err
405				}
406			}
407			d.Head = time.Since(t0)
408	
409			blocks := time.Now()
410			if err := p.stack.SetAdaLN(adaln); err != nil {
411				return nil, nil, err
412			}
413			// Phase one: the noise refiners over the image stream alone. The
414			// unified rotary table's first rows are the image's, so the same
415			// table serves both this phase and the layers.
416			//
417			// On the device path the embedder *is* the upload: the [4096, 64]
418			// patches go up as fp16 and the [4096, 3840] stream is written by a
419			// GEMM that never leaves the device.
420			if x != nil {
421				if err := p.stack.Upload(x, 0, p.imgTotal); err != nil {
422					return nil, nil, err
423				}
424			} else if err := p.gpuHead.Embed(patches, p.imgTotal); err != nil {
425				return nil, nil, err
426			}
427			if err := p.stack.Run(p.noiseRefiner); err != nil {
428				return nil, nil, fmt.Errorf("pipeline: step %d noise refiners: %w", step, err)
429			}
430			// Phase three: the refined caption is appended behind the refined
431			// image, in place, and the 30 layers run over the two.
432			tail := refined
433			if p.ctl.staleCaption {
434				tail = cap
435			}
436			if err := p.stack.Upload(tail, p.imgTotal, unified); err != nil {
437				return nil, nil, err
438			}
439			if err := p.stack.Run(p.layers); err != nil {
440				return nil, nil, fmt.Errorf("pipeline: step %d layers: %w", step, err)
441			}
442			d.Blocks = time.Since(blocks)
443	
444			t0 = time.Now()
445			// Only the image tokens reach the final layer; the caption's rows are
446			// produced and discarded, as they are in diffusers' unpatchify. On the
447			// device path the tail runs over the padded image stream, because the
448			// GEMM's tile divides that and not the token count, and the extra
449			// rows are dropped here rather than not computed.
450			var final *dit.Mat
451			if p.gpuHead == nil || p.ctl.cpuHead {
452				stream := p.stack.Read(p.stack.TensorX(), p.cfg.Dim)
453				image := &dit.Mat{Rows: p.imgTokens, Cols: stream.Cols, Data: stream.Data[:p.imgTokens*stream.Cols]}
454				if final, err = p.head.Final(image, adaln); err != nil {
455					return nil, nil, err
456				}
457			} else {
458				if final, err = p.gpuHead.Final(p.imgTotal); err != nil {
459					return nil, nil, err
460				}
461				final = &dit.Mat{Rows: p.imgTokens, Cols: final.Cols, Data: final.Data[:p.imgTokens*final.Cols]}
462			}
463			out, err := p.head.Unpatchify(final, p.latentH, p.latentW)
464			if err != nil {
465				return nil, nil, err
466			}
467			// The pipeline negates the transformer's output before the step: the
468			// model predicts the velocity towards the noise and the schedule runs
469			// away from it.
470			if !p.ctl.noNegate {
471				for i := range out {
472					out[i] = -out[i]
473				}
474			}
475			if err := p.sched.Step(step, latents, out); err != nil {
476				return nil, nil, err
477			}
478			d.Head += time.Since(t0)
479	
480			tm.Steps = append(tm.Steps, d.Blocks+d.Head)
481			if progress != nil {
482				progress(d)
483			}
484		}
485	
486		// --- the decode ----------------------------------------------------
487		t0 = time.Now()
488		latent := vae.NewTensor(1, p.cfg.InChan, p.latentH, p.latentW)
489		for i, v := range latents {
490			latent.Data[i] = float32(float64(v)/p.scale + p.shift)
491		}
492		img, err := p.dec.Apply(latent)
493		if err != nil {
494			return nil, nil, fmt.Errorf("pipeline: vae: %w", err)
495		}
496		tm.Decode = time.Since(t0)
497		tm.Total = time.Since(whole)
498		return img, tm, nil
499	}
500	
501	// Residency reports what the pipeline holds on the device, by stage. The VAE
502	// is its own column because stage 8 gave it two arenas of each kind: the
503	// convolutions read fp16 fragment-tile copies of the filters and a blocked
504	// fp16 copy of each input, beside the fp32 originals the scalar kernels and
505	// the rest of the graph still use.
506	func (p *Pipeline) Residency() (encoder, transformer, vae, activations int) {
507		vaeW32, vaeW16 := p.dec.WeightBytes()
508		return p.enc.WeightBytes() + p.enc.ActivationBytes(),
509			p.stack.WeightBytes(),
510			vaeW32 + vaeW16,
511			p.stack.ActivationBytes() + p.dec.ActivationBytes() + p.dec.F16ActivationBytes()
512	}
513	
514	func seq(lo, hi int) []int {
515		out := make([]int, 0, hi-lo)
516		for i := lo; i < hi; i++ {
517			out = append(out, i)
518		}
519		return out
520	}
521

