package pipeline

import (
	"fmt"
	"math/rand"
	"time"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/dit"
	"strix-halo-vulkan/zimage/qwen"
	"strix-halo-vulkan/zimage/tokenizer"
	"strix-halo-vulkan/zimage/vae"
)

// Options configures a Pipeline. The sizes are fixed at construction because
// every arena in it is: the text encoder is built for a maximum prompt, the
// transformer for a maximum unified sequence, and the VAE decoder for one
// latent grid.
type Options struct {
	Model     string // the checkpoint root, holding transformer/, vae/, ...
	Width     int    // image pixels; a multiple of 16
	Height    int
	Steps     int
	MaxPrompt int // the longest prompt the text encoder is built for
	// CPUHead runs the patch embedder and the final layer on the host, which
	// is what stage 6 did. It is the slow path kept beside the device one
	// (PIPELINE.md's rule), and it is a flag rather than a test-only control
	// because the measurement that justifies stage 9 is the difference
	// between the two on the same image.
	CPUHead bool
	// UnfusedLayout keeps the two pure-layout dispatches stage 10 removed --
	// `pack v` and `narrow ctx` -- as their own passes. Same reason as
	// CPUHead: the slow path is what the fast one is measured against, and
	// the measurement is the difference between the two on the same image.
	UnfusedLayout bool
}

// Defaults fills in what was left zero.
func (o Options) Defaults() Options {
	if o.Model == "" {
		o.Model = "models/Z-Image-Turbo"
	}
	if o.Width == 0 {
		o.Width = 1024
	}
	if o.Height == 0 {
		o.Height = o.Width
	}
	if o.Steps == 0 {
		o.Steps = 8
	}
	if o.MaxPrompt == 0 {
		o.MaxPrompt = 512
	}
	return o
}

// vaeScale is how much larger the image is than the latent grid: the decoder
// upsamples 8x and the transformer's patch size is 2, so both sides must be a
// multiple of 16.
const vaeScale = 8

// Pipeline holds every stage resident: 7.07 GB of text encoder, 12.54 GB of
// transformer and the VAE, plus their activation arenas. Construction is what
// costs -- a little over twenty seconds, nearly all of it staging weights --
// and a Pipeline then generates images without touching the disk again.
type Pipeline struct {
	opt Options

	tok *tokenizer.Tokenizer
	enc *qwen.GPUEncoder

	cfg   *dit.Config
	head  *dit.Head
	stack *dit.GPUStack
	// gpuHead is the patch embedder and the final layer on the device (stage
	// 9). nil is the host path of stage 6, which is what it is measured
	// against and what runs if the shapes do not suit the kernels.
	gpuHead *dit.GPUHead

	dec *vae.GPUDecoder

	sched *FlowMatchEuler
	scale float64 // the VAE's scaling_factor
	shift float64 // its shift_factor

	// The three phases' block indices, in the order the transformer runs
	// them. StackBlocks lays the stack out this way, so they follow from the
	// config's counts.
	noiseRefiner, contextRefiner, layers []int

	// ctl is empty in every real use except for Options.CPUHead; see controls.
	ctl controls

	latentH, latentW int
	imgTokens        int // the image stream before padding
	imgTotal         int // and after
	maxUnified       int
}

// Timings is what one image cost, by stage.
type Timings struct {
	Encode   time.Duration // tokenizer and the text encoder
	Caption  time.Duration // cap_embedder and the context refiners, once per image
	Steps    []time.Duration
	Decode   time.Duration // the VAE
	Total    time.Duration
	Tokens   int // the prompt's length
	CapTotal int // the caption stream after padding
	Unified  int // the sequence the layers ran over
}

// controls are the deliberate breakages the negative control switches on.
// They live here rather than in the test because what each of them breaks is
// the *composition* -- the order the three stages run in, the sign the
// scheduler is handed, which rows of the unified sequence the caption's rotary
// positions belong to -- and none of that is reachable from outside
// GenerateFrom. Every one of them still produces an image.
type controls struct {
	// noNegate leaves the transformer's output as it is instead of negating
	// it before the Euler step. The model predicts the velocity towards the
	// noise and the schedule runs away from it; nothing about the tensor says
	// which way it points.
	noNegate bool
	// staleCaption puts the *embedded* caption behind the image instead of
	// the one the context refiners produced, i.e. skips the phase whose whole
	// output is 32 rows of a 4128-row sequence.
	staleCaption bool
	// capPosFromZero starts the caption's rotary positions at 0 rather than
	// 1, which is the off-by-one the checkpoint invites: nothing downstream
	// of a rotary table can tell that every caption token moved one place.
	capPosFromZero bool
	// cpuHead runs the patch embedder and the final layer on the host, which
	// is what stage 6 did and what stage 9's device path is compared against.
	// Not a breakage -- it is the slow path, kept (PIPELINE.md's rule).
	cpuHead bool
}

// Step is what a progress callback is told after each denoising step.
//
// Blocks is the time in the transformer's blocks and Head the time in the CPU
// head and tail; they are separated because the head is the pipeline's one
// unoptimised piece. Latents is the state the step left, [C, H, W] -- it is the
// pipeline's own buffer and the next step overwrites it, so a callback that
// wants to keep it (to decode a preview, say) has to copy it.
type Step struct {
	Index          int
	Blocks, Head   time.Duration
	Latents        []float32
	Sigma, NextSig float64
}

// New builds the pipeline, staging every weight onto the device.
func New(dev *vk.Device, opt Options) (*Pipeline, error) {
	opt = opt.Defaults()
	if opt.Width%(2*vaeScale) != 0 || opt.Height%(2*vaeScale) != 0 {
		return nil, fmt.Errorf("pipeline: %dx%d; both sides must be a multiple of %d", opt.Width, opt.Height, 2*vaeScale)
	}
	p := &Pipeline{
		opt:     opt,
		latentH: opt.Height / vaeScale,
		latentW: opt.Width / vaeScale,
	}

	schedCfg, err := LoadSchedulerConfig(opt.Model + "/scheduler")
	if err != nil {
		return nil, err
	}
	if p.sched, err = NewFlowMatchEuler(opt.Steps, schedCfg); err != nil {
		return nil, err
	}

	if p.tok, err = tokenizer.Load(opt.Model + "/tokenizer"); err != nil {
		return nil, fmt.Errorf("pipeline: tokenizer: %w", err)
	}
	encCfg, err := qwen.LoadConfig(opt.Model + "/text_encoder")
	if err != nil {
		return nil, fmt.Errorf("pipeline: text encoder config: %w", err)
	}
	encSet, err := safetensors.OpenSet(opt.Model + "/text_encoder")
	if err != nil {
		return nil, fmt.Errorf("pipeline: text encoder: %w", err)
	}
	p.enc, err = qwen.NewGPUEncoder(dev, encSet, encCfg, encCfg.EncoderLayers(), opt.MaxPrompt, nil)
	encSet.Close()
	if err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: text encoder: %w", err)
	}

	if p.cfg, err = dit.LoadConfig(opt.Model + "/transformer"); err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: transformer config: %w", err)
	}
	ditSet, err := safetensors.OpenSet(opt.Model + "/transformer")
	if err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: transformer: %w", err)
	}
	defer ditSet.Close()
	if p.head, err = dit.LoadHead(ditSet, p.cfg); err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: transformer head: %w", err)
	}
	if p.cfg.CapFeat != encCfg.HiddenSize {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: the transformer wants %d caption features, the encoder produces %d",
			p.cfg.CapFeat, encCfg.HiddenSize)
	}

	p.imgTokens = (p.latentH / p.head.Patch) * (p.latentW / p.head.Patch)
	p.imgTotal = dit.PadTo(p.imgTokens)
	p.maxUnified = p.imgTotal + dit.PadTo(opt.MaxPrompt)
	// The rotary table is replaced per run and per phase; this one only has
	// to be the right size and inside the axes' ranges.
	ids, err := p.head.PositionIDs(opt.MaxPrompt, p.latentH, p.latentW)
	if err != nil {
		p.Destroy()
		return nil, err
	}
	rope, err := dit.NewRoPE(ids, p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
	if err != nil {
		p.Destroy()
		return nil, err
	}
	if p.stack, err = dit.NewGPUStack(dev, ditSet, p.cfg, rope, p.maxUnified, nil); err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: transformer: %w", err)
	}
	// The head on the device. It is a small object beside the stack -- 5 MB
	// of weights and four pipelines -- and it needs the stack to exist first,
	// because the residual stream it writes and reads is the stack's arena.
	p.ctl.cpuHead = opt.CPUHead
	p.stack.FuseLayout = !opt.UnfusedLayout
	if p.gpuHead, err = dit.NewGPUHead(p.stack, p.head); err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: transformer head: %w", err)
	}
	nr := p.cfg.NRefiner
	p.noiseRefiner = seq(0, nr)
	p.contextRefiner = seq(nr, 2*nr)
	p.layers = seq(2*nr, 2*nr+p.cfg.NLayers)

	vaeCfg := vae.FluxConfig()
	p.scale, p.shift = vaeCfg.ScalingFactor, vaeCfg.ShiftFactor
	cpu, err := vae.LoadDecoder(opt.Model+"/vae", vaeCfg)
	if err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: vae: %w", err)
	}
	if p.dec, err = vae.NewGPUDecoder(dev, cpu, p.latentH, p.latentW); err != nil {
		p.Destroy()
		return nil, fmt.Errorf("pipeline: vae: %w", err)
	}
	return p, nil
}

// Destroy releases every device resource.
func (p *Pipeline) Destroy() {
	if p.dec != nil {
		p.dec.Destroy()
	}
	// Before the stack: the head's pipelines are bound to the stack's arenas.
	if p.gpuHead != nil {
		p.gpuHead.Destroy()
	}
	if p.stack != nil {
		p.stack.Destroy()
	}
	if p.enc != nil {
		p.enc.Destroy()
	}
	p.dec, p.stack, p.enc, p.gpuHead = nil, nil, nil, nil
}

// Scheduler is the noise schedule the pipeline walks.
func (p *Pipeline) Scheduler() *FlowMatchEuler { return p.sched }

// Latent is the grid the transformer denoises: 16 channels at an eighth of
// the image's size.
func (p *Pipeline) Latent() (channels, height, width int) {
	return p.cfg.InChan, p.latentH, p.latentW
}

// Noise draws an initial latent from a seeded Gaussian.
func (p *Pipeline) Noise(seed int64) []float32 {
	rng := rand.New(rand.NewSource(seed))
	out := make([]float32, p.cfg.InChan*p.latentH*p.latentW)
	for i := range out {
		out[i] = float32(rng.NormFloat64())
	}
	return out
}

// Encode runs the tokenizer and the text encoder, and returns the caption
// stream the transformer's context refiners take: the hidden state embedded
// by cap_embedder, padded with the learned token.
func (p *Pipeline) Encode(prompt string) (*dit.Mat, int, error) {
	ids, err := p.tok.EncodePrompt(prompt)
	if err != nil {
		return nil, 0, fmt.Errorf("pipeline: tokenizing: %w", err)
	}
	if len(ids) > p.opt.MaxPrompt {
		return nil, 0, fmt.Errorf("pipeline: the prompt is %d tokens, the encoder was built for %d",
			len(ids), p.opt.MaxPrompt)
	}
	hidden, err := p.enc.Forward(ids)
	if err != nil {
		return nil, 0, fmt.Errorf("pipeline: text encoder: %w", err)
	}
	cap, err := p.head.EmbedCaption(&dit.Mat{Rows: hidden.Rows, Cols: hidden.Cols, Data: hidden.Data})
	if err != nil {
		return nil, 0, err
	}
	return cap, len(ids), nil
}

// Generate runs the whole pipeline: prompt in, decoded image out. The image
// is [3, H, W] in [-1, 1], which is what the VAE produces and what a PNG
// writer has to map.
func (p *Pipeline) Generate(prompt string, seed int64, progress func(Step)) (*vae.Tensor, *Timings, error) {
	latents := p.Noise(seed)
	return p.GenerateFrom(prompt, latents, progress)
}

// GenerateFrom is Generate over an initial latent that is given rather than
// drawn, which is what makes an end-to-end comparison against diffusers
// possible: the two RNGs do not agree and nothing else in the pipeline is
// random.
func (p *Pipeline) GenerateFrom(prompt string, latents []float32, progress func(Step)) (*vae.Tensor, *Timings, error) {
	if want := p.cfg.InChan * p.latentH * p.latentW; len(latents) != want {
		return nil, nil, fmt.Errorf("pipeline: %d latents, want C*H*W = %d", len(latents), want)
	}
	tm := &Timings{}
	whole := time.Now()

	// --- the caption, once per image ---------------------------------
	t0 := time.Now()
	cap, tokens, err := p.Encode(prompt)
	if err != nil {
		return nil, nil, err
	}
	tm.Encode = time.Since(t0)
	tm.Tokens, tm.CapTotal = tokens, cap.Rows
	unified := p.imgTotal + cap.Rows
	tm.Unified = unified

	ids, err := p.head.PositionIDs(tokens, p.latentH, p.latentW)
	if err != nil {
		return nil, nil, err
	}
	if p.ctl.capPosFromZero {
		for i := p.imgTotal; i < len(ids); i++ {
			ids[i][0]--
		}
	}
	ropeUnified, err := dit.NewRoPE(ids, p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
	if err != nil {
		return nil, nil, err
	}
	ropeCap, err := dit.NewRoPE(ids[p.imgTotal:], p.cfg.AxesDims, p.cfg.AxesLens, p.cfg.RopeTheta)
	if err != nil {
		return nil, nil, err
	}

	// The context refiners are the transformer's one phase that depends on
	// neither the timestep nor the latents -- diffusers builds them with
	// modulation=False -- so they run once per image and not once per step.
	t0 = time.Now()
	if err := p.stack.SetRoPE(ropeCap); err != nil {
		return nil, nil, err
	}
	if err := p.stack.Upload(cap, 0, cap.Rows); err != nil {
		return nil, nil, err
	}
	if err := p.stack.Run(p.contextRefiner); err != nil {
		return nil, nil, fmt.Errorf("pipeline: context refiners: %w", err)
	}
	refined := p.stack.Read(p.stack.TensorX(), p.cfg.Dim)
	tm.Caption = time.Since(t0)

	if err := p.stack.SetRoPE(ropeUnified); err != nil {
		return nil, nil, err
	}

	// --- the denoising loop -------------------------------------------
	for step := 0; step < p.sched.Steps(); step++ {
		t0 = time.Now()
		d := Step{Index: step, Latents: latents,
			Sigma: p.sched.Sigmas[step], NextSig: p.sched.Sigmas[step+1]}

		adaln, err := p.head.Timestep(p.sched.ModelT(step))
		if err != nil {
			return nil, nil, err
		}
		patches, err := p.head.Patchify(latents, p.latentH, p.latentW)
		if err != nil {
			return nil, nil, err
		}
		var x *dit.Mat
		if p.gpuHead == nil || p.ctl.cpuHead {
			if x, err = p.head.EmbedImage(patches); err != nil {
				return nil, nil, err
			}
		}
		d.Head = time.Since(t0)

		blocks := time.Now()
		if err := p.stack.SetAdaLN(adaln); err != nil {
			return nil, nil, err
		}
		// Phase one: the noise refiners over the image stream alone. The
		// unified rotary table's first rows are the image's, so the same
		// table serves both this phase and the layers.
		//
		// On the device path the embedder *is* the upload: the [4096, 64]
		// patches go up as fp16 and the [4096, 3840] stream is written by a
		// GEMM that never leaves the device.
		if x != nil {
			if err := p.stack.Upload(x, 0, p.imgTotal); err != nil {
				return nil, nil, err
			}
		} else if err := p.gpuHead.Embed(patches, p.imgTotal); err != nil {
			return nil, nil, err
		}
		if err := p.stack.Run(p.noiseRefiner); err != nil {
			return nil, nil, fmt.Errorf("pipeline: step %d noise refiners: %w", step, err)
		}
		// Phase three: the refined caption is appended behind the refined
		// image, in place, and the 30 layers run over the two.
		tail := refined
		if p.ctl.staleCaption {
			tail = cap
		}
		if err := p.stack.Upload(tail, p.imgTotal, unified); err != nil {
			return nil, nil, err
		}
		if err := p.stack.Run(p.layers); err != nil {
			return nil, nil, fmt.Errorf("pipeline: step %d layers: %w", step, err)
		}
		d.Blocks = time.Since(blocks)

		t0 = time.Now()
		// Only the image tokens reach the final layer; the caption's rows are
		// produced and discarded, as they are in diffusers' unpatchify. On the
		// device path the tail runs over the padded image stream, because the
		// GEMM's tile divides that and not the token count, and the extra
		// rows are dropped here rather than not computed.
		var final *dit.Mat
		if p.gpuHead == nil || p.ctl.cpuHead {
			stream := p.stack.Read(p.stack.TensorX(), p.cfg.Dim)
			image := &dit.Mat{Rows: p.imgTokens, Cols: stream.Cols, Data: stream.Data[:p.imgTokens*stream.Cols]}
			if final, err = p.head.Final(image, adaln); err != nil {
				return nil, nil, err
			}
		} else {
			if final, err = p.gpuHead.Final(p.imgTotal); err != nil {
				return nil, nil, err
			}
			final = &dit.Mat{Rows: p.imgTokens, Cols: final.Cols, Data: final.Data[:p.imgTokens*final.Cols]}
		}
		out, err := p.head.Unpatchify(final, p.latentH, p.latentW)
		if err != nil {
			return nil, nil, err
		}
		// The pipeline negates the transformer's output before the step: the
		// model predicts the velocity towards the noise and the schedule runs
		// away from it.
		if !p.ctl.noNegate {
			for i := range out {
				out[i] = -out[i]
			}
		}
		if err := p.sched.Step(step, latents, out); err != nil {
			return nil, nil, err
		}
		d.Head += time.Since(t0)

		tm.Steps = append(tm.Steps, d.Blocks+d.Head)
		if progress != nil {
			progress(d)
		}
	}

	// --- the decode ----------------------------------------------------
	t0 = time.Now()
	latent := vae.NewTensor(1, p.cfg.InChan, p.latentH, p.latentW)
	for i, v := range latents {
		latent.Data[i] = float32(float64(v)/p.scale + p.shift)
	}
	img, err := p.dec.Apply(latent)
	if err != nil {
		return nil, nil, fmt.Errorf("pipeline: vae: %w", err)
	}
	tm.Decode = time.Since(t0)
	tm.Total = time.Since(whole)
	return img, tm, nil
}

// Residency reports what the pipeline holds on the device, by stage. The VAE
// is its own column because stage 8 gave it two arenas of each kind: the
// convolutions read fp16 fragment-tile copies of the filters and a blocked
// fp16 copy of each input, beside the fp32 originals the scalar kernels and
// the rest of the graph still use.
func (p *Pipeline) Residency() (encoder, transformer, vae, activations int) {
	vaeW32, vaeW16 := p.dec.WeightBytes()
	return p.enc.WeightBytes() + p.enc.ActivationBytes(),
		p.stack.WeightBytes(),
		vaeW32 + vaeW16,
		p.stack.ActivationBytes() + p.dec.ActivationBytes() + p.dec.F16ActivationBytes()
}

func seq(lo, hi int) []int {
	out := make([]int, 0, hi-lo)
	for i := lo; i < hi; i++ {
		out = append(out, i)
	}
	return out
}

package api

import (
	"context"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"strconv"

	"strix-halo-vulkan/audio"
)

// Backend is what every adapter has in common: the model ids it answers to.
// They are what GET /v1/models lists, and what a request's "model" field is
// matched against -- leniently, because a client configured for "tts-1" is
// still asking for the only voice model this process has.
type Backend interface {
	Models() []Model
}

// SpeechBackend synthesises speech. It returns samples rather than a file
// because the container is the HTTP layer's business: the same utterance is a
// WAV or raw PCM depending on the request's response_format, and a model
// should not know which was asked for.
type SpeechBackend interface {
	Backend
	// Speak turns text, or IPA phonemes, into mono PCM. The request carries
	// the voice and the speed; a backend that cannot honour either returns
	// an error rather than substituting one silently.
	Speak(ctx context.Context, req *SpeechRequest) (*audio.Clip, error)
	// Voices are the voice names Speak accepts, sorted. GET /v1/models
	// reports them so a client can populate a menu without a second call.
	Voices() []string
}

// TranscriptionBackend turns audio into text.
//
// The clip is decoded by the HTTP layer and handed over already in the
// float32 form every model in this repository reads, so a backend never
// parses a container. It does still check the sample rate, because resampling
// is a signal-processing decision and silently doing it at the door would
// hide a client sending 44.1 kHz into a 16 kHz model.
type TranscriptionBackend interface {
	Backend
	Transcribe(ctx context.Context, clip *audio.Clip, req *TranscriptionRequest) (*TranscriptionResponse, error)
}

// CompletionBackend generates text.
//
// **The signature is a streaming one**, and the buffered response is written
// in terms of it rather than the other way round. That is not a preference:
// a token on this part costs 12 ms (LLM.md L8d), so a 500-token answer is six
// seconds, and an interface that returned the whole thing would make the
// streamed endpoint impossible to build on top of it while the buffered one
// is trivial to build on this. emit is called once per token; an error from
// it -- a client that hung up -- stops the loop and comes back from Complete.
//
// What crosses this boundary is model-shaped and not HTTP-shaped: the backend
// says what it generated and what stopped it, and the handler decides what a
// `chat.completion` object looks like. Rendering the conversation into the
// checkpoint's own chat template is the backend's, because the template is
// part of the checkpoint.
type CompletionBackend interface {
	Backend
	Complete(ctx context.Context, req *CompletionRequest, emit func(Delta) error) (*CompletionResult, error)
}

// CompletionResult is how a generation ended.
//
// The text is not in it. The handler has already seen every token through
// emit, and a backend that returned the whole answer as well would be a
// second copy of it that could disagree with the first.
type CompletionResult struct {
	// FinishReason is "stop" -- the model emitted an end-of-generation
	// token, or ran into a stop sequence -- "length", or "tool_calls".
	FinishReason string
	// StopSequence is the stop sequence that ended the generation, when one
	// did. OpenAI's envelopes fold that into "stop" and Anthropic's reports
	// it, which is the only reason it is carried separately.
	StopSequence string
	// ToolCalls are the calls the generation made, whole. They are not
	// streamed: a call is not a call until it has closed, and its arguments
	// are not JSON until they have been typed against the tool's schema.
	ToolCalls []*ToolCall
	Usage     Usage
}

// EmbeddingBackend is a placeholder: it lets a process advertise a model it
// has loaded through GET /v1/models, and carries no method yet, because
// there is no embedding model in this repository to give it one (GOALS.md).
type EmbeddingBackend interface{ Backend }

// ImageBackend is a placeholder; see EmbeddingBackend. `zimage/pipeline` is
// the right shape for one -- resident weights, Generate(prompt, seed,
// progress) -- but its width and height are fixed at construction, so
// `aspect_ratio` is a residency question rather than a parameter and the
// interface should not pretend otherwise.
type ImageBackend interface{ Backend }

// ErrUnsupported is what a backend returns when a request is well formed but
// asks for something this model cannot do -- an unknown voice, a sample rate
// it does not take. It becomes a 400 rather than a 500, because the client
// can fix it.
var ErrUnsupported = errors.New("unsupported request")

// errorBody is OpenAI's error envelope, which is what every client of this
// API already knows how to read.
type errorBody struct {
	Message string `json:"message"`
	Type    string `json:"type"`
	Code    string `json:"code,omitempty"`
}

type errorResponse struct {
	Error errorBody `json:"error"`
}

// writeError answers with OpenAI's error shape. typ is the coarse class the
// client switches on ("invalid_request_error", "server_error").
func writeError(w http.ResponseWriter, status int, typ, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(errorResponse{Error: errorBody{Message: msg, Type: typ}})
}

// badRequest is the client's fault; serverError is ours, and is the one that
// gets logged, because nobody sees the response body of a 500 at 3am.
func badRequest(w http.ResponseWriter, msg string) {
	writeError(w, http.StatusBadRequest, "invalid_request_error", msg)
}

func serverError(w http.ResponseWriter, where string, err error) {
	log.Printf("api: %s: %v", where, err)
	writeError(w, http.StatusInternalServerError, "server_error", err.Error())
}

// backendError maps a backend's error onto a status. ErrUnsupported is the
// client's fault; anything else is a run that went wrong.
func backendError(w http.ResponseWriter, where string, err error) {
	if errors.Is(err, ErrUnsupported) {
		badRequest(w, err.Error())
		return
	}
	if errors.Is(err, context.Canceled) {
		// The client hung up mid-run. There is nobody to answer.
		log.Printf("api: %s: client cancelled", where)
		return
	}
	serverError(w, where, err)
}

// notLoaded is the 501 an endpoint gives when the process was started without
// the model behind it. The message names the flag, because the answer to
// "why did this 501" is almost always "it was not asked for on the command
// line".
func notLoaded(w http.ResponseWriter, what, flag string) {
	writeError(w, http.StatusNotImplemented, "not_implemented",
		what+" is not loaded; start the server with "+flag)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// tooLarge answers 413 when err is the body cap being hit, and reports
// whether it did. A body over the limit is its own failure and not a
// malformed one: the client can retry with a shorter clip.
func tooLarge(w http.ResponseWriter, err error) bool {
	var maxErr *http.MaxBytesError
	if !errors.As(err, &maxErr) {
		return false
	}
	writeError(w, http.StatusRequestEntityTooLarge, "invalid_request_error",
		"the request body is larger than this server's limit of "+
			strconv.FormatInt(maxErr.Limit, 10)+" bytes")
	return true
}

// decodeJSON reads a JSON request body into v, answering the client itself if
// it cannot. It reports whether the handler should carry on.
func decodeJSON(w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(r.Body).Decode(v); err != nil {
		if tooLarge(w, err) {
			return false
		}
		badRequest(w, "malformed JSON body: "+err.Error())
		return false
	}
	return true
}

// Package api provides the HTTP API for the AI backend.
//
// It is the routing layer and nothing else. Every endpoint is answered by a
// backend interface this package *defines* and does not implement -- see
// backend.go -- so `api` imports no checkpoint loader, no model and no
// Vulkan, and its tests run in milliseconds against fakes. `backend/` holds
// the adapters that own the weights and the device; `cmd/serve` parses the
// flags and wires the two together.
//
// A missing backend is not a missing route. Every endpoint is always served;
// one whose backend is nil answers 501. That is what makes `serve -tts`
// without `-stt` the same binary with a smaller resident set rather than a
// different build, and it is what lets a client discover what this instance
// can do from GET /v1/models instead of from a connection error.
package api

import (
	"net/http"
	"time"

	"strix-halo-vulkan/util"
)

// Server is one instance of the API: a bearer token and whichever backends
// the process loaded. The zero value serves every route, asks for no token
// and answers 501 to everything, which is what a test that only exercises the
// middleware wants.
type Server struct {
	// Token is the bearer token every /v1 request must carry. Empty means
	// the API is open, which is for a loopback-only development run; it is
	// never the default in cmd/serve.
	Token string

	// MaxUploadBytes bounds a request body that carries a file -- an audio
	// upload, an image to edit. Zero takes defaultMaxUpload.
	MaxUploadBytes int64

	// LogBodies prints each request's and response's text in the access
	// log. It is off by default because this server's bodies are
	// conversations: a chat endpoint with body logging on writes every
	// prompt and every answer to disk as a side effect of having a log.
	// With it off the log still carries the method, the path, the status,
	// the duration and the sizes.
	LogBodies bool

	// The backends, any of which may be nil.
	Speech        SpeechBackend
	Transcription TranscriptionBackend
	Completion    CompletionBackend
	Embedding     EmbeddingBackend
	Image         ImageBackend
}

// Handler builds the mux. It is a fresh *http.ServeMux rather than
// http.DefaultServeMux so that two Servers -- a test's and the process's, or
// two tests' -- do not collide on the global one.
func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()

	// No request / response, it's just headers. This is registered outside
	// the authorization middleware on purpose: browsers never send
	// Authorization on a preflight.
	mux.Handle("OPTIONS /v1/", s.log(http.HandlerFunc(util.CORSPreflight)))

	// Output: ModelsResponse{}
	mux.Handle("GET /v1/models", s.route(s.handleModels))

	// The OG completion endpoint
	// Input: CompletionRequest{}, Output: CompletionResponse{}
	mux.Handle("POST /v1/chat/completions", s.route(s.handleChatCompletions))
	// OpenAI's "Responses" API
	// Input: ResponsesRequest{}, Output: ResponsesResponse{}
	mux.Handle("POST /v1/responses", s.route(s.handleResponses))
	// Anthropic's "Messages" API
	// Input: MessagesRequest{}, Output: MessagesResponse{}
	mux.Handle("POST /v1/messages", s.route(s.handleMessages))

	// Input: EmbeddingRequest{}, Output: EmbeddingResponse{}
	mux.Handle("POST /v1/embeddings", s.route(s.handleEmbeddings))

	// Input: SpeechRequest{}, Output: SpeechResponse{}
	mux.Handle("POST /v1/audio/speech", s.route(s.handleSpeech))

	// Input: TranscriptionRequest{}, Output: TranscriptionResponse{}
	mux.Handle("POST /v1/audio/transcriptions", s.route(s.handleTranscription))

	// Input: ImageGenerationRequest{}, Output: ImageGenerationResponse{}
	mux.Handle("POST /v1/images/generations", s.route(s.handleImageGeneration))
	// Input: ImageEditRequest{}, Output: ImageGenerationResponse{}
	mux.Handle("POST /v1/images/edits", s.route(s.handleImageEdit))

	return mux
}

// route is the middleware stack every endpoint carries, outermost first.
//
// The body limit is outside the logger on purpose: the logger reads small
// bodies so it can print them, and it must never be handed an unbounded one.
func (s *Server) route(h http.HandlerFunc) http.Handler {
	return s.limitBody(s.log(s.authorize(addHeaders(h))))
}

// log is the access log, with or without the bodies.
func (s *Server) log(h http.Handler) http.HandlerFunc {
	return util.LogRequestFunc(s.LogBodies)(h)
}

// limitBody caps what a request may carry. Past the cap the read fails with
// an *http.MaxBytesError, which the handlers turn into a 413.
func (s *Server) limitBody(fs http.Handler) http.HandlerFunc {
	limit := s.MaxUploadBytes
	if limit <= 0 {
		limit = defaultMaxUpload
	}
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Body != nil {
			r.Body = http.MaxBytesReader(w, r.Body, limit)
		}
		fs.ServeHTTP(w, r)
	}
}

// HTTPServer wraps Handler in an http.Server with timeouts chosen for what
// this API actually carries.
//
// ReadHeaderTimeout is short because a stalled header is never legitimate.
// ReadTimeout is minutes rather than seconds because a transcription request
// is an audio upload. **WriteTimeout is zero**, i.e. unbounded: a response
// here is a model run, and a deadline on the write side would cut off a long
// synthesis or a streamed completion mid-token. What bounds a slow client
// instead is IdleTimeout between requests.
func (s *Server) HTTPServer(addr string) *http.Server {
	return &http.Server{
		Addr:              addr,
		Handler:           s.Handler(),
		ReadHeaderTimeout: 15 * time.Second,
		ReadTimeout:       10 * time.Minute,
		WriteTimeout:      0,
		IdleTimeout:       2 * time.Minute,
	}
}

func (s *Server) authorize(fs http.Handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if s.Token == "" || r.Header.Get("Authorization") == "Bearer "+s.Token {
			fs.ServeHTTP(w, r)
			return
		}

		w.WriteHeader(http.StatusUnauthorized)
		// A write that fails here is a client that hung up, which is not
		// this process's problem: log nothing and return.
		_, _ = w.Write([]byte("Unauthorized"))
	}
}

func addHeaders(fs http.Handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Prevent clickjacking attacks
		w.Header().Set("X-Frame-Options", "DENY")

		// Prevent MIME-type sniffing
		w.Header().Set("X-Content-Type-Options", "nosniff")

		// Enable strict HTTPS
		w.Header().Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")

		// Control permitted sources for content
		w.Header().Set("Content-Security-Policy", "default-src 'none'; frame-ancestors 'none';")

		// Prevent information leakage
		w.Header().Set("Referrer-Policy", "no-referrer")

		// Cross-origin isolation
		w.Header().Set("Cross-Origin-Opener-Policy", "same-origin")
		w.Header().Set("Cross-Origin-Embedder-Policy", "require-corp")
		w.Header().Set("Cross-Origin-Resource-Policy", "same-site")
		w.Header().Set("X-Permitted-Cross-Domain-Policies", "none")

		// Set CORS headers (reflects the request Origin when allow-listed)
		util.SetCORSHeaders(w, r)

		// Remove server header
		w.Header().Del("Server")

		// Opt out of robots
		w.Header().
			Set("X-Robots-Tag", "noindex, nofollow, noarchive, nositelinkssearchbox, nosnippet, notranslate, noimageindex")

		// Disable caching
		w.Header().Set("Cache-Control", "no-cache, must-revalidate, max-age=0")

		fs.ServeHTTP(w, r)
	}
}

package api

import "net/http"

// The endpoints whose models are not wired yet.
//
// They are registered rather than left off the mux so that a client gets a
// 501 with a message saying what is missing, instead of a 404 that looks like
// a misspelled path. Each one becomes a handler when its backend arrives:
// embeddings when there is an embedding model at all (GOALS.md), and images
// when `zimage`'s pipeline is wired in. The nil check each one will then
// carry -- "loaded, or not asked for on the command line" -- is the one the
// four endpoints that do answer already have.

func (s *Server) handleEmbeddings(w http.ResponseWriter, _ *http.Request) {
	notImplementedYet(w, "/v1/embeddings", "an embedding model")
}

func (s *Server) handleImageGeneration(w http.ResponseWriter, _ *http.Request) {
	notImplementedYet(w, "/v1/images/generations", "the image model")
}

func (s *Server) handleImageEdit(w http.ResponseWriter, _ *http.Request) {
	notImplementedYet(w, "/v1/images/edits", "the image model")
}

// notImplementedYet is the other 501: not "this process was started without
// the model" but "no flag would have loaded it", because the route is not
// written yet. The two are worth distinguishing, because only one of them is
// fixed by a restart.
func notImplementedYet(w http.ResponseWriter, route, what string) {
	writeError(w, http.StatusNotImplemented, "not_implemented",
		route+" is not implemented on this server yet: "+what+" is not wired up")
}

// Command serve is the long-lived HTTP server: the models in this repository
// behind an OpenAI-shaped API.
//
// What it loads is what it is told to load. Each vertical is a flag, and a
// vertical that was not asked for is not in memory and answers 501 with a
// message naming the flag that would have loaded it:
//
//	go run ./cmd/serve -tts -stt
//	go run ./cmd/serve -llm                         # the language model, 84 GB resident
//	go run ./cmd/serve -llm -llm-layers 4           # the server, in 7 GB, for the HTTP side
//	go run ./cmd/serve -tts -voice bm_george -addr :8080
//	go run ./cmd/serve -stt -max-audio 300          # five-minute clips
//	go run ./cmd/serve -tts -gpu=false              # the CPU reference
//
// The endpoints that answer today are GET /v1/models, POST
// /v1/chat/completions, POST /v1/audio/speech and POST
// /v1/audio/transcriptions. The rest are routed and answer 501: /v1/responses
// and /v1/messages are the same model in two more envelopes, embeddings wait
// on there being an embedding model at all, and images on zimage's pipeline
// being wired in.
//
// Two things about the device are worth knowing before reading the timings.
// **Requests are serialised at the queue**, because a vk.Device has one and
// nothing in `vk` is externally synchronised -- the server is concurrent at
// the HTTP layer and serial at the GPU, which is also the only way these
// models make sense on a part with one 236 GB/s bus. And **-tts-gpu stages
// per request**: kokoro's arenas are sized for one utterance's frame count,
// so the device path pays a staging pass every time and is off by default
// until that is measured (see backend.TTS.synthesize).
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"strix-halo-vulkan/api"
	"strix-halo-vulkan/backend"
)

// defaultToken is what the API has always used. It is a flag so that a
// deployment can change it, and an empty one opens the server, which is only
// sensible on loopback.
const defaultToken = "womblesofwimbledon"

// defaultLLMModel names the shard rather than the directory it is in, because
// that directory now holds three checkpoints -- the model, Unsloth's imatrix
// and the MTP draft head -- and a directory holding more than one is
// ambiguous rather than convenient.
const defaultLLMModel = "models/Qwen3.8-Flash-Next-GGUF/Qwen3.8-Flash-Next-UD-Q4_K_XL-00001-of-00004.gguf"

func main() {
	log.SetFlags(log.Ltime)
	addr := flag.String("addr", "127.0.0.1:8080", "address to listen on; loopback by default")
	token := flag.String("token", defaultToken, "bearer token; empty serves without authorization")
	gpu := flag.Bool("gpu", true, "run the models on Vulkan where they have a resident path")
	maxUpload := flag.Int64("max-upload", 128, "largest request body that carries a file, in MB")
	logBodies := flag.Bool("log-bodies", false,
		"print each request and response body in the access log; off because they are conversations")

	tts := flag.Bool("tts", false, "load Kokoro-82M and serve /v1/audio/speech")
	ttsModel := flag.String("tts-model", "models/Kokoro-82M", "converted kokoro checkpoint directory")
	ttsGPU := flag.Bool("tts-gpu", false, "run kokoro on the device; it stages per utterance, see the package comment")
	lexicon := flag.String("lexicon", "models/misaki", "misaki lexicon directory; empty takes phonemes only")
	espeak := flag.Bool("espeak", true, "use espeak-ng for words outside the lexicon")
	british := flag.Bool("british", false, "use the en-GB lexicon and fallback")
	voice := flag.String("voice", "af_heart", "voice a request that names none gets")
	noise := flag.Int64("noise", 0, "seed for the vocoder's excitation noise; 0 leaves it off")

	llmOn := flag.Bool("llm", false, "load qwen3.8-flash-next and serve /v1/chat/completions")
	llmModel := flag.String("llm-model", defaultLLMModel, "GGUF checkpoint, shard or directory")
	llmCtx := flag.Int("llm-ctx", 4096, "cache cells: the longest conversation, prompt plus completion")
	llmBatch := flag.Int("llm-batch", 512, "tokens the prefill arenas hold; a longer prompt is prefilled in chunks of it")
	llmMax := flag.Int("llm-max-tokens", 1024, "tokens a request that names no max_tokens gets")
	llmLayers := flag.Int("llm-layers", 0, "stage only the first N layers; 0 is the model, anything else is a fast start and not an answer")

	stt := flag.Bool("stt", false, "load parakeet-tdt-0.6b-v3 and serve /v1/audio/transcriptions")
	sttModel := flag.String("stt-model", "models/parakeet-tdt-0.6b-v3", "parakeet checkpoint directory")
	maxAudio := flag.Float64("max-audio", 60, "longest clip the transcription arenas are sized for, in seconds")
	flag.Parse()

	if !*tts && !*stt && !*llmOn {
		log.Printf("warning: no model was asked for; every endpoint will answer 501. " +
			"Pass -llm, -tts and/or -stt.")
	}

	srv := &api.Server{Token: *token, MaxUploadBytes: *maxUpload << 20, LogBodies: *logBodies}

	// The device is opened once and shared. Only the models that were asked
	// for decide whether it is needed at all: a CPU-only run should not fail
	// on a machine without Vulkan.
	var dev *backend.Device
	if *gpu && (*stt || *llmOn || (*tts && *ttsGPU)) {
		d, err := backend.OpenDevice("strix-halo-serve")
		if err != nil {
			log.Fatalf("opening the device: %v", err)
		}
		defer d.Close()
		dev = d
		log.Printf("device: %s", d.Name())
	}

	if *tts {
		start := time.Now()
		ttsDev := dev
		if !*ttsGPU {
			ttsDev = nil
		}
		b, err := backend.NewTTS(backend.TTSOptions{
			Model: *ttsModel, Lexicon: *lexicon, Espeak: *espeak, British: *british,
			Voice: *voice, Device: ttsDev, Noise: *noise,
		})
		if err != nil {
			log.Fatal(err)
		}
		defer b.Close()
		srv.Speech = b
		log.Printf("tts: %s, %d voices, %s, in %v", *ttsModel, len(b.Voices()),
			where(ttsDev != nil), time.Since(start).Round(time.Millisecond))
	}

	if *stt {
		start := time.Now()
		b, err := backend.NewSTT(backend.STTOptions{
			Model: *sttModel, Device: dev, MaxSeconds: *maxAudio,
		})
		if err != nil {
			log.Fatal(err)
		}
		defer b.Close()
		srv.Transcription = b
		log.Printf("stt: %s, clips to %.0f s, %s, in %v", *sttModel, *maxAudio,
			where(dev != nil), time.Since(start).Round(time.Millisecond))
	}

	// The language model is staged last, and on purpose: it is most of this
	// machine's memory and tens of seconds of staging, so a mistake in a
	// speech flag is reported before the wait rather than after it.
	if *llmOn {
		start := time.Now()
		b, err := backend.NewLLM(backend.LLMOptions{
			Model: *llmModel, Device: dev, Context: *llmCtx, Batch: *llmBatch,
			MaxTokens: *llmMax, Layers: *llmLayers,
		})
		if err != nil {
			log.Fatal(err)
		}
		defer b.Close()
		srv.Completion = b
		layers := "every layer"
		if *llmLayers > 0 {
			layers = fmt.Sprintf("the first %d layers only", *llmLayers)
		}
		log.Printf("llm: %s, %s, %d cells of context, %d-token batches, in %v",
			*llmModel, layers, b.Context(), *llmBatch, time.Since(start).Round(time.Millisecond))
	}

	if *token == "" {
		log.Printf("warning: -token is empty; this server authorizes nothing")
	}
	if err := listen(srv, *addr); err != nil {
		log.Fatal(err)
	}
}

func where(gpu bool) string {
	if gpu {
		return "on the device"
	}
	return "on the host"
}

// listen serves until the process is interrupted, then drains.
//
// The drain matters here more than it does for a CRUD server: a request in
// flight owns the GPU queue, and killing the process underneath it would
// leave the device to the driver to clean up. Shutdown waits for the handler
// to finish, and the deferred backend teardown in main then runs with nothing
// dispatching.
func listen(srv *api.Server, addr string) error {
	hs := srv.HTTPServer(addr)
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errs := make(chan error, 1)
	go func() {
		log.Printf("listening on http://%s", addr)
		for _, route := range []string{
			"/v1/models", "/v1/chat/completions", "/v1/audio/speech", "/v1/audio/transcriptions",
		} {
			log.Printf("  %s", route)
		}
		errs <- hs.ListenAndServe()
	}()

	select {
	case err := <-errs:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return err
	case <-ctx.Done():
		log.Printf("shutting down; waiting for requests in flight")
		shutdown, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		if err := hs.Shutdown(shutdown); err != nil {
			return fmt.Errorf("draining: %w", err)
		}
		return nil
	}
}

