541	// size of each arena. It allocates nothing and reads no tensor: the sizes
542	// follow from the config, so the whole 12 GB layout is decided -- and can be
543	// checked -- before the first weight is touched.
544	func (g *GPUStack) planBanks(specs []blockSpec, bankBytes int) (total32 int, bankElems []int, err error) {
545		// fp32: the rotary table once, then per block the five norms and -- only
546		// if it is modulated -- the adaLN projection and its bias. The table is
547		// cos and sin over headDim/2 pairs per token, since RoPE rotates adjacent
548		// components as one complex number.
549		ropeElems := 2 * g.tokens * (g.headDim / 2)
550		total32 = ropeElems
551		perBlock32 := func(modulated bool) int {
552			n := 4*g.dim + 2*g.headDim
553			if modulated {
554				n += 4*g.dim*g.adaIn + 4*g.dim
555			}
556			return n
557		}
558		// fp16: the seven projections, in the layout their kernel reads.
559		shapes := g.projShapes()
560		perProj := make(map[Proj]int, len(projOrder))
561		perBlock16 := 0
562		for _, r := range projOrder {
563			v, ok := variantFor(g.plan[r])
564			if !ok {
565				return 0, nil, fmt.Errorf("dit: no GEMM kernel %q (have %v)", g.plan[r], GEMMKernels())
566			}
567			n := bElems(shapes[r][0], shapes[r][1], v.layout)
568			if g.ctl.wrongBLayout {
569				// The control stages a weight in a layout its kernel does not
570				// expect, and the [N, K+pad] one is the largest of the three, so
571				// the bank is sized for it -- but only when the control is on:
572				// the pad is 0.35 GB across the real stack's 34 blocks.
573				n = max(n, bElems(shapes[r][0], shapes[r][1], 0))
574			}
575			perProj[r] = n
576			perBlock16 += n
577		}
578		if perBlock16*2 > bankBytes {
579			return 0, nil, fmt.Errorf("dit: one block's weights are %d MB and a bank holds %d MB",
580				(perBlock16*2)>>20, bankBytes>>20)
581		}
582	
583		g.w = make([]blockWeights, len(specs))
584		cur := -1
585		for i, s := range specs {
586			if s.modulated && g.adaIn == 0 {
587				return 0, nil, fmt.Errorf("dit: block %s is modulated but the stack has no adaLN shape", s.prefix)
588			}
589			w := blockWeights{modulated: s.modulated, prefix: s.prefix, bOff: make(map[Proj]uint32, len(projOrder))}
590			w.norm1 = uint32(total32)
591			w.norm2 = w.norm1 + uint32(g.dim)
592			w.ffn1 = w.norm2 + uint32(g.dim)
593			w.ffn2 = w.ffn1 + uint32(g.dim)
594			w.normQ = w.ffn2 + uint32(g.dim)
595			w.normK = w.normQ + uint32(g.headDim)
596			if s.modulated {
597				w.adaLN = w.normK + uint32(g.headDim)
598				w.adaLNBias = w.adaLN + uint32(4*g.dim*g.adaIn)
599			}
600			total32 += perBlock32(s.modulated)
601	
602			// A new bank whenever this block would not fit the current one. They
603			// come out uneven -- 12, 12, 10 for the real model -- and that is
604			// fine: what has to hold is that a block is in exactly one.
605			if cur < 0 || (bankElems[cur]+perBlock16)*2 > bankBytes {
606				bankElems = append(bankElems, 0)
607				cur = len(bankElems) - 1
608			}
609			w.bank = cur
610			for _, r := range projOrder {
611				w.bOff[r] = uint32(bankElems[cur])
612				bankElems[cur] += perProj[r]
613			}
614			g.w[i] = w
615		}
616		return total32, bankElems, nil
617	}
