			w16 = g.stageConvWeights(w16)
		}
		if g.w16buf, err = dev.NewBuffer(len(w16) * 2); err != nil {
			g.Destroy()
			return nil, fmt.Errorf("vae: fp16 weight buffer (%d MB): %w", (len(w16)*2)>>20, err)
		}
