// milliseconds rounds a time to the millisecond, which is three orders finer
// than the 80 ms frame it came from and is there for one reason: 41 frames of
// 0.08 s is 3.2800000000000002 in binary floating point, and nobody reading a
// transcript should have to see that.
func milliseconds(t float64) float64 { return math.Round(t*1000) / 1000 }

// segments groups words into sentences, which is what a caller asking for
// segment timestamps wants and the only division this model offers: it
// punctuates, so a sentence end is a token and not a guess about silence.
func segments(words []api.TranscriptionWord) []api.TranscriptionSegment {
	var out []api.TranscriptionSegment
	var cur *api.TranscriptionSegment
	for _, w := range words {
		if cur == nil {
			out = append(out, api.TranscriptionSegment{ID: len(out), Start: w.Start})
			cur = &out[len(out)-1]
		}
		if cur.Text != "" {
			cur.Text += " "
		}
		cur.Text += w.Word
		cur.End = w.End
		if strings.HasSuffix(w.Word, ".") || strings.HasSuffix(w.Word, "?") ||
			strings.HasSuffix(w.Word, "!") {
			cur = nil
		}
	}
	return out
}

// Package backend holds the model adapters the HTTP API is served from: one
// per vertical, each owning its weights, its device residency and the lock
// that serialises requests against them.
//
// It exists so that `api` can stay a routing layer with no model in it and no
// Vulkan behind it, and so that the adapters are testable and reusable
// outside `cmd/serve`. The direction of the dependency is
// `cmd/serve -> backend -> api`, never the other way: `api` declares the
// interfaces (api.SpeechBackend, api.TranscriptionBackend) and the types here
// satisfy them.
package backend

import (
	"fmt"
	"sync"

	"strix-halo-vulkan/vk"
)

// strixHaloDeviceID is this machine's iGPU (gfx1151 / RADV STRIX_HALO), which
// every command in this repository prefers when it is present.
const strixHaloDeviceID = 0x1586

// Device is the Vulkan device plus the lock that makes it safe to serve from.
//
// **The lock is not a performance choice, it is a correctness one.** A
// vk.Device holds a single queue, and nothing in `vk` is externally
// synchronised: two requests recording and submitting at the same time is
// undefined behaviour and not merely contention. Every run -- and every
// staging pass, which also records and submits -- goes through Do, so the
// server is concurrent at the HTTP layer and serial at the device.
//
// That is also the right shape for the hardware. The models here are sized to
// saturate the iGPU on their own; two of them interleaved would not go
// faster, they would just share a 236 GB/s bus.
type Device struct {
	inst *vk.Instance
	dev  *vk.Device
	mu   sync.Mutex
}

// OpenDevice picks this machine's iGPU, or the first device with a compute
// queue, and enables the features every model in this repository is built
// against: fp16, cooperative matrix, and subgroup size control where the
// driver reports it.
func OpenDevice(appName string) (*Device, error) {
	inst, err := vk.NewInstance(appName)
	if err != nil {
		return nil, err
	}
	devices, err := inst.PhysicalDevices()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	if len(devices) == 0 {
		inst.Destroy()
		return nil, fmt.Errorf("backend: no Vulkan devices")
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		inst.Destroy()
		return nil, err
	}
	return &Device{inst: inst, dev: dev}, nil
}

// Do runs fn with the device held. It is the only way a caller outside this
// package touches the device.
func (d *Device) Do(fn func(*vk.Device) error) error {
	d.mu.Lock()
	defer d.mu.Unlock()
	return fn(d.dev)
}

// Name is the physical device's name, for the startup banner.
func (d *Device) Name() string { return d.dev.Physical().Name }

// Close destroys the device and the instance. Every model staged on it must
// already have been destroyed.
func (d *Device) Close() {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.dev.Destroy()
	d.inst.Destroy()
}

package api

import (
	"encoding/binary"
	"errors"
	"math"
	"net/http"
	"strconv"
)

// OpenAI Speech Request
// https://platform.openai.com/docs/api-reference/audio/createSpeech

// SpeechRequest is the OpenAI Speech Request
type SpeechRequest struct {
	host           string
	Input          string  `json:"input"`
	Model          string  `json:"model"`
	Voice          string  `json:"voice"`
	ResponseFormat string  `json:"response_format"` // mp3, wav, opus, flac, pcm
	Speed          float64 `json:"speed"`           // 0.5 - 2.0
	Stream         bool    `json:"stream"`          // false
	// Phonemes is an extension, not OpenAI's: IPA to speak directly,
	// bypassing grapheme-to-phoneme. Kokoro's vocabulary is 178 IPA symbols
	// and the front end that reaches them is a separate model's worth of
	// rules (SPEECH.md T5), so a caller that already has phonemes -- a test
	// against the reference dump, a caller with its own lexicon -- says so
	// here and the server does not guess. It wins over Input when both are
	// set.
	Phonemes string `json:"phonemes,omitempty"`
}

// SpeechResponse is the OpenAI Speech Response
type SpeechResponse []byte

// speedRange is what the endpoint accepts. OpenAI's own range is 0.25 to 4;
// kokoro reads it as a duration divisor, so the extremes are intelligible
// rather than merely legal.
const (
	minSpeed = 0.25
	maxSpeed = 4.0
)

// handleSpeech synthesises an utterance and returns it as one body.
//
// It does not stream. OpenAI's streaming speech is chunked audio as the model
// produces it, and kokoro does not produce it that way: the durations for the
// whole utterance are decided before a single sample exists (SPEECH.md T2),
// so there is nothing to send early. A request with stream:true is refused
// rather than answered with a whole body pretending to be a stream.
func (s *Server) handleSpeech(w http.ResponseWriter, r *http.Request) {
	if s.Speech == nil {
		notLoaded(w, "text to speech", "-tts")
		return
	}
	var req SpeechRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	if req.Input == "" && req.Phonemes == "" {
		badRequest(w, "input is empty")
		return
	}
	if req.Stream {
		badRequest(w, "streaming speech is not implemented; the utterance's durations are decided before any samples exist")
		return
	}
	if req.Speed == 0 {
		req.Speed = 1
	}
	if req.Speed < minSpeed || req.Speed > maxSpeed {
		badRequest(w, "speed is "+strconv.FormatFloat(req.Speed, 'g', -1, 64)+
			", outside ["+strconv.FormatFloat(minSpeed, 'g', -1, 64)+", "+
			strconv.FormatFloat(maxSpeed, 'g', -1, 64)+"]")
		return
	}
	format := req.ResponseFormat
	if format == "" {
		format = "wav"
	}
	switch format {
	case "wav", "pcm":
	default:
		badRequest(w, "response_format "+strconv.Quote(format)+
			" is not supported; this server encodes wav and pcm (16-bit signed, little endian, mono)")
		return
	}

	clip, err := s.Speech.Speak(r.Context(), &req)
	if err != nil {
		backendError(w, "speech", err)
		return
	}
	if clip == nil || len(clip.Samples) == 0 {
		serverError(w, "speech", errEmptyAudio)
		return
	}

	var body []byte
	switch format {
	case "wav":
		if body, err = clip.EncodeWAV(); err != nil {
			serverError(w, "speech", err)
			return
		}
		w.Header().Set("Content-Type", "audio/wav")
	case "pcm":
		body = encodePCM16(clip.Samples)
		w.Header().Set("Content-Type", "audio/pcm")
	}
	// The rate is in the WAV header but not in raw PCM, and a client that
	// asked for PCM still has to know what to play it at.
	w.Header().Set("X-Sample-Rate", strconv.Itoa(clip.Rate))
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(body)
}

// encodePCM16 is audio.Clip.EncodeWAV's sample conversion without the
// container, scaled by 32767 and clamped for the same reason: a full-scale
// +1.0 that 32768 would wrap to the most negative sample stays at the top of
// the range instead of inverting.
func encodePCM16(samples []float32) []byte {
	out := make([]byte, 0, 2*len(samples))
	for _, s := range samples {
		v := math.Round(float64(s) * 32767)
		if v > 32767 {
			v = 32767
		} else if v < -32768 {
			v = -32768
		}
		out = binary.LittleEndian.AppendUint16(out, uint16(int16(v)))
	}
	return out
}

// errEmptyAudio is its own value so the handler's two failure paths -- a
// backend error, and a backend that returned nothing without saying why --
// are distinguishable in the log.
var errEmptyAudio = errors.New("the speech backend returned no samples")

