package api

import (
	"net/http"
	"sort"
)

type ModelsResponse struct {
	Object string  `json:"object"`
	Data   []Model `json:"data"`
}

// Model represents a single model in the list of models.
type Model struct {
	ID      string `json:"id"`
	Object  string `json:"object"`   // "model"
	OwnedBy string `json:"owned_by"` // "organization_owner"
	// Voices is this model's voice names, for a speech model. It is not part
	// of OpenAI's model object -- clients ignore fields they do not know --
	// and it is here because the alternative is a second round trip to find
	// out what /v1/audio/speech will accept.
	Voices []string `json:"voices,omitempty"`
}

// backends returns every loaded backend, in the order GET /v1/models lists
// them. A nil field is a model this process was not started with.
func (s *Server) backends() []Backend {
	var out []Backend
	if s.Completion != nil {
		out = append(out, s.Completion)
	}
	if s.Embedding != nil {
		out = append(out, s.Embedding)
	}
	if s.Speech != nil {
		out = append(out, s.Speech)
	}
	if s.Transcription != nil {
		out = append(out, s.Transcription)
	}
	if s.Image != nil {
		out = append(out, s.Image)
	}
	return out
}

// handleModels lists what this process actually loaded, which is the only
// honest answer: a server started without -tts does not have a speech model,
// and saying so here is cheaper for a client than a 501 later.
func (s *Server) handleModels(w http.ResponseWriter, _ *http.Request) {
	resp := ModelsResponse{Object: "list", Data: []Model{}}
	seen := map[string]bool{}
	for _, b := range s.backends() {
		for _, m := range b.Models() {
			if seen[m.ID] {
				continue
			}
			seen[m.ID] = true
			if m.Object == "" {
				m.Object = "model"
			}
			resp.Data = append(resp.Data, m)
		}
	}
	if s.Speech != nil {
		voices := s.Speech.Voices()
		sort.Strings(voices)
		for i := range resp.Data {
			if speaks(s.Speech, resp.Data[i].ID) {
				resp.Data[i].Voices = voices
			}
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// speaks reports whether id is one of the speech backend's own models, so
// that the voice list is attached to those and not to the transcription
// model sitting beside them.
func speaks(b SpeechBackend, id string) bool {
	for _, m := range b.Models() {
		if m.ID == id {
			return true
		}
	}
	return false
}

package api

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// Server-Sent Events, which all three chat envelopes are streamed over.
//
// The three disagree about almost everything -- OpenAI's chat endpoint sends
// unnamed frames and ends with a `[DONE]` sentinel, its Responses API names
// every frame and numbers them, Anthropic's names them and does not number
// them -- so what is shared is only this: the headers, the framing, and a
// flush after every frame. A streaming endpoint that does not flush is a
// buffered endpoint with extra syntax.

// sse is one streamed response. Creating it commits the status code, which is
// why every check a handler wants to answer with a status has to happen
// first.
type sse struct {
	w   http.ResponseWriter
	rc  *http.ResponseController
	seq int
}

func newSSE(w http.ResponseWriter) *sse {
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Connection", "keep-alive")
	// Neither a proxy nor this process may hold a frame back: the whole
	// point of the endpoint is that a token is visible when it exists.
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	return &sse{w: w, rc: http.NewResponseController(w)}
}

// send writes one frame. An empty name writes no `event:` line, which is what
// OpenAI's chat endpoint expects and what the other two never want.
func (s *sse) send(event string, v any) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	if event != "" {
		if _, err := fmt.Fprintf(s.w, "event: %s\n", event); err != nil {
			return err
		}
	}
	if _, err := fmt.Fprintf(s.w, "data: %s\n\n", b); err != nil {
		return err
	}
	s.seq++
	return s.rc.Flush()
}

// done writes OpenAI's end-of-stream sentinel, which is not JSON and not an
// event: it is the literal `data: [DONE]`.
func (s *sse) done() error {
	if _, err := fmt.Fprint(s.w, "data: [DONE]\n\n"); err != nil {
		return err
	}
	return s.rc.Flush()
}

// next is the sequence number of the frame about to be sent. The Responses
// API numbers its events and clients use the numbers to spot a gap.
func (s *sse) next() int { return s.seq }

