// ImageGeometry is what an image backend will accept. It is reported on the
// model object in GET /v1/models for the same reason the voice list is: the
// alternative is a client discovering the limit from a 400.
//
// MaxWidth and MaxHeight are a *ceiling on each side and not a promise about
// the pair*: what the arenas actually bound is the number of image tokens, so
// a backend built for 1024x1024 runs 512x2048 and refuses 1024x1088. MaxPixels
// says that directly, and is the number a client should check.
type ImageGeometry struct {
	Width, Height       int `json:"-"`
	MaxWidth, MaxHeight int `json:"-"`
	// Multiple is what both sides must be a multiple of.
	Multiple int `json:"size_multiple"`
	// MaxPixels is width*height at the ceiling.
	MaxPixels int `json:"max_pixels"`
	// Steps is the default denoising schedule's length.
	Steps int `json:"steps"`

	// DefaultSize and MaxSize are the two pairs as OpenAI spells a size, so a
	// client can echo one straight back into a request.
	DefaultSize string `json:"default_size"`
	MaxSize     string `json:"max_size"`
}

