func TestAspectRatioFitsTheCeiling(t *testing.T) {
	for _, c := range []struct {
		ratio         string
		geo           ImageGeometry
		width, height int
	}{
		{"1:1", ImageGeometry{MaxWidth: 1024, MaxHeight: 1024, Multiple: 16}, 1024, 1024},
