		{"wrapped unsupported", &fakeImage{err: wrapUnsupported("the prompt is 700 tokens")}, 400},
		{"broken", &fakeImage{err: errors.New("device lost")}, 500},
		{"nothing at all", &fakeImage{nil_: true}, 500},
