19	// fakeImage is an image backend that renders a flat colour, records what it
20	// was asked for, and answers a geometry. Everything in this file is about the
21	// translation between a request and that struct, which is the whole of what
22	// `api` owns: the model is a device away.
23	type fakeImage struct {
24		reqs           []ImageRequest
25		geo            ImageGeometry
26		err            error
27		returnsNothing bool // (nil, nil), which a backend should never do
28	}
29	
30	func (f *fakeImage) Models() []Model {
31		return []Model{{ID: "z-image-turbo", Object: "model", OwnedBy: "local"}}
32	}
33	
34	func (f *fakeImage) Geometry() ImageGeometry {
35		if f.geo.Width == 0 {
36			return ImageGeometry{Width: 1024, Height: 1024, MaxWidth: 1024, MaxHeight: 1024,
37				Multiple: 16, Steps: 8}
38		}
39		return f.geo
40	}
41	
42	func (f *fakeImage) Generate(_ context.Context, req *ImageRequest) (*ImageResult, error) {
43		f.reqs = append(f.reqs, *req)
44		if f.err != nil {
45			return nil, f.err
46		}
47		if f.returnsNothing {
48			return nil, nil
49		}
50		w, h := req.Width, req.Height
51		if w == 0 || h == 0 {
52			w, h = f.Geometry().Width, f.Geometry().Height
53		}
54		img := image.NewRGBA(image.Rect(0, 0, w, h))
55		for y := 0; y < h; y++ {
56			for x := 0; x < w; x++ {
57				img.Set(x, y, color.RGBA{1, 2, 3, 255})
58			}
59		}
60		seed := int64(99)
61		if req.Seed != nil {
62			seed = *req.Seed
63		}
64		steps := req.Steps
65		if steps == 0 {
66			steps = f.Geometry().Steps
67		}
68		return &ImageResult{Image: img, Width: w, Height: h, Steps: steps, Seed: seed}, nil
69	}
