// geomFor resolves a request's size against the pipeline's. A zero side takes
// the default, and one side given alone takes the other from it -- which is
// what "512" means when a client says it.
//
// **What bounds a request is the image stream's row count and not the sides**,
// because that is what the arenas are: the transformer runs over
// imgTotal + caption rows, and the VAE's arena is a high-water mark over
// tensors whose size is the latent's area. So a pipeline built for 1024x1024
// also runs 512x2048, and refuses 1024x1088 -- which is 68 rows more than it
// has, at sides that both look small enough.
func (p *Pipeline) geomFor(width, height int) (geom, error) {
	switch {
	case width == 0 && height == 0:
		return p.def, nil
	case width == 0:
		width = height
	case height == 0:
		height = width
	}
	if width == p.def.width && height == p.def.height {
		return p.def, nil
	}
	g, err := newGeom(width, height, p.head.Patch)
	if err != nil {
		return geom{}, err
	}
	if g.imgTokens > p.max.imgTokens {
		return geom{}, fmt.Errorf(
			"pipeline: %dx%d is %d image tokens, and these arenas were built for %d (%dx%d)",
			width, height, g.imgTokens, p.max.imgTokens, p.max.width, p.max.height)
	}
	return g, nil
}

