19	// fakeImage is an image backend that renders a flat colour, records what it
20	// was asked for, and answers a geometry. Everything in this file is about the
21	// translation between a request and that struct, which is the whole of what
22	// `api` owns: the model is a device away.
23	type fakeImage struct {
24		reqs           []ImageRequest
25		geo            ImageGeometry
26		err            error
27		returnsNothing bool // (nil, nil), which a backend should never do
28	}
29	
30	func (f *fakeImage) Models() []Model {
31		return []Model{{ID: "z-image-turbo", Object: "model", OwnedBy: "local"}}
32	}
33	
34	func (f *fakeImage) Geometry() ImageGeometry {
35		if f.geo.Width == 0 {
36			return ImageGeometry{Width: 1024, Height: 1024, MaxWidth: 1024, MaxHeight: 1024,
37				Multiple: 16, Steps: 8}
38		}
39		return f.geo
40	}
41	
42	func (f *fakeImage) Generate(_ context.Context, req *ImageRequest) (*ImageResult, error) {
43		f.reqs = append(f.reqs, *req)
44		if f.err != nil {
45			return nil, f.err
46		}
47		if f.returnsNothing {
48			return nil, nil
49		}
50		w, h := req.Width, req.Height
51		if w == 0 || h == 0 {
52			w, h = f.Geometry().Width, f.Geometry().Height
53		}
54		img := image.NewRGBA(image.Rect(0, 0, w, h))
55		for y := 0; y < h; y++ {
56			for x := 0; x < w; x++ {
57				img.Set(x, y, color.RGBA{1, 2, 3, 255})
58			}
59		}
60		seed := int64(99)
61		if req.Seed != nil {
62			seed = *req.Seed
63		}
64		steps := req.Steps
65		if steps == 0 {
66			steps = f.Geometry().Steps
67		}
68		return &ImageResult{Image: img, Width: w, Height: h, Steps: steps, Seed: seed}, nil
69	}
70	
71	func generate(t *testing.T, s *Server, body any) (*httptest.ResponseRecorder, ImageGenerationResponse) {
72		t.Helper()
73		rec := do(t, s, jsonRequest("POST", "/v1/images/generations", body))
74		var got ImageGenerationResponse
75		if rec.Code == http.StatusOK {
76			if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
77				t.Fatalf("%v: %s", err, rec.Body)
78			}
79		}
80		return rec, got
81	}
82	
83	func TestImageGenerationDefaultSize(t *testing.T) {
84		fake := &fakeImage{}
85		s := &Server{Token: "t", Image: fake}
86		rec, got := generate(t, s, ImageGenerationRequest{Prompt: "a red fox in the snow"})
87		if rec.Code != http.StatusOK {
88			t.Fatalf("status %d: %s", rec.Code, rec.Body)
89		}
90		if len(fake.reqs) != 1 {
91			t.Fatalf("%d backend calls", len(fake.reqs))
92		}
93		// A request that named no size is handed the backend's own, resolved
94		// here: the backend should never have to ask what its default was.
95		if fake.reqs[0].Width != 1024 || fake.reqs[0].Height != 1024 {
96			t.Errorf("backend got %dx%d, want the default 1024x1024",
97				fake.reqs[0].Width, fake.reqs[0].Height)
98		}
99		if fake.reqs[0].Seed != nil {
100			t.Errorf("seed %v, want nil so the backend draws one", *fake.reqs[0].Seed)
101		}
102		if got.Size != "1024x1024" || got.OutputFormat != "png" {
103			t.Errorf("echoed %q / %q", got.Size, got.OutputFormat)
104		}
105		if len(got.Data) != 1 {
106			t.Fatalf("%d images", len(got.Data))
107		}
108		// The seed the server drew comes back, because that is the only way a
109		// client can ask for the same image twice.
110		if got.Data[0].Seed != 99 || got.Data[0].Steps != 8 {
111			t.Errorf("seed %d, steps %d", got.Data[0].Seed, got.Data[0].Steps)
112		}
113		raw, err := base64.StdEncoding.DecodeString(got.Data[0].B64JSON)
114		if err != nil {
115			t.Fatal(err)
116		}
117		cfg, format, err := image.DecodeConfig(bytes.NewReader(raw))
118		if err != nil {
119			t.Fatal(err)
120		}
121		if format != "png" || cfg.Width != 1024 || cfg.Height != 1024 {
122			t.Errorf("%s %dx%d", format, cfg.Width, cfg.Height)
123		}
124	}
125	
126	func TestImageGenerationSizeReachesTheBackend(t *testing.T) {
127		for _, c := range []struct {
128			name          string
129			req           ImageGenerationRequest
130			width, height int
131		}{
132			{"explicit", ImageGenerationRequest{Prompt: "p", Size: "512x768"}, 512, 768},
133			{"auto", ImageGenerationRequest{Prompt: "p", Size: "auto"}, 1024, 1024},
