135			// what the pipeline change bought: half the tokens, the same arenas.
136			{"landscape", ImageGenerationRequest{Prompt: "p", Size: "1024x512"}, 1024, 512},
137			{"aspect ratio", ImageGenerationRequest{Prompt: "p", AspectRatio: "16:9"}, 1024, 576},
138			// Size wins over aspect_ratio, because one of them is OpenAI's field
139			// and a client that sent both meant the one every other server reads.
140			{"size beats ratio", ImageGenerationRequest{Prompt: "p", Size: "256x256", AspectRatio: "16:9"}, 256, 256},
141		} {
142			t.Run(c.name, func(t *testing.T) {
143				fake := &fakeImage{}
144				s := &Server{Image: fake}
145				rec, got := generate(t, s, c.req)
146				if rec.Code != http.StatusOK {
