12	// The resolution is a per-run parameter and the arenas are a ceiling, so
13	// everything about resolving a request's size is arithmetic on a patch size
14	// and needs neither a checkpoint nor a device.
15	func TestGeomFor(t *testing.T) {
16		// A pipeline built for 1024x1024, without anything in it: geomFor reads
17		// the head's patch size and the two geometries and nothing else.
18		max, err := newGeom(1024, 1024, 2)
19		if err != nil {
20			t.Fatal(err)
21		}
22		p := &Pipeline{head: &dit.Head{Patch: 2}, max: max, def: max}
23	
24		for _, c := range []struct {
25			name          string
26			w, h          int
27			width, height int
28			tokens        int
29		}{
30			{"the default", 0, 0, 1024, 1024, 4096},
31			// One side alone means a square, which is what a client typing "512"
32			// into a box means.
33			{"width alone", 512, 0, 512, 512, 1024},
34			{"height alone", 0, 512, 512, 512, 1024},
35			{"smaller", 512, 512, 512, 512, 1024},
36			{"landscape", 1024, 512, 1024, 512, 2048},
37			{"portrait", 512, 1024, 512, 1024, 2048},
38			{"the smallest there is", 16, 16, 16, 16, 1},
39		} {
40			t.Run(c.name, func(t *testing.T) {
41				g, err := p.geomFor(c.w, c.h)
42				if err != nil {
43					t.Fatal(err)
44				}
45				if g.width != c.width || g.height != c.height {
46					t.Errorf("%dx%d, want %dx%d", g.width, g.height, c.width, c.height)
47				}
48				if g.imgTokens != c.tokens {
49					t.Errorf("%d image tokens, want %d", g.imgTokens, c.tokens)
50				}
51				if g.latentH != c.height/vaeScale || g.latentW != c.width/vaeScale {
52					t.Errorf("latent %dx%d for a %dx%d image", g.latentH, g.latentW, c.width, c.height)
53				}
54				if g.imgTotal < g.imgTokens || g.imgTotal%dit.SeqMultiOf != 0 {
55					t.Errorf("%d tokens padded to %d, which is not a multiple of %d",
56						g.imgTokens, g.imgTotal, dit.SeqMultiOf)
57				}
58			})
59		}
60	}
61	
62	// The sizes that are refused, and why each one has to be refused rather than
63	// rounded: the arenas are what they are, and a silently different image is
64	// worse than an error.
65	func TestGeomForRefuses(t *testing.T) {
66		max, err := newGeom(1024, 1024, 2)
67		if err != nil {
68			t.Fatal(err)
69		}
70		p := &Pipeline{head: &dit.Head{Patch: 2}, max: max, def: max}
71	
72		for _, c := range []struct {
73			name, want string
74			w, h       int
75		}{
76			{"off the grid", "multiple of 16", 1000, 1000},
77			{"negative", "is not an image", -16, 16},
78			{"past the arenas", "every side has to be inside it", 2048, 2048},
79			{"past them on one side", "every side has to be inside it", 1024, 1088},
80			// **The same area in another shape is refused, and that is the
81			// finding rather than a conservative choice.** By the transformer's
82			// arithmetic 512x2048 is the same 4096 rows as the square these
83			// arenas were built as. TestSameAreaTallerShapeIsRefused measures why
84			// it is not enough.
85			{"the same area, taller", "every side has to be inside it", 512, 2048},
86		} {
87			t.Run(c.name, func(t *testing.T) {
88				if _, err := p.geomFor(c.w, c.h); err == nil {
89					t.Fatalf("%dx%d was accepted", c.w, c.h)
90				} else if !strings.Contains(err.Error(), c.want) {
91					t.Errorf("%v, want it to mention %q", err, c.want)
92				}
93			})
94		}
95	}
96	
97	// TestOneePipelineManySizes is the claim the geometry arithmetic above cannot
98	// make on its own: that the three graphs actually run at a size other than the
99	// one their arenas were allocated for.
100	//
101	// It is the only place that can say so, because each stage's own tests build
102	// their arenas for the size they then run. What breaks here if the change is
103	// wrong is not subtle -- a transformer whose run length did not follow the
104	// upload reads the previous run's rows, and a VAE whose graph did not follow
105	// the latent writes past its arena -- but it is invisible to every test below
